from pathlib import Path
root=Path(__file__).resolve().parents[2]
checks=[]
def check(label, cond):
    checks.append((label,bool(cond)))

def txt(p): return (root/p).read_text(encoding='utf-8')
core=txt(Path('src/main/java/com/example/editor/grammar/core/GrammarTextualEditorCustomization.java'))
monaco=txt(Path('frontend/src/grammar-designer/GrammarMonacoEditor.tsx'))
designer=txt(Path('frontend/src/grammar-designer/GrammarDesigner.tsx'))
textual=txt(Path('frontend/src/textual-model-editor/TextualModelEditor.tsx'))
stand=txt(Path('src/main/resources/standalone-template/frontend/textual-app.js'))
xtext=txt(Path('src/main/java/com/example/editor/integration/adapter/xtext/XtextTechnologyAdapter.java'))
vscode=txt(Path('src/main/java/com/example/editor/integration/adapter/vscode/VsCodeExtensionTechnologyAdapter.java'))
langium=txt(Path('src/main/java/com/example/editor/integration/adapter/langium/LangiumTechnologyAdapter.java'))
integration=txt(Path('frontend/src/integration-designer/integrationDesignerOptions.ts'))
css=txt(Path('frontend/src/grammar-designer/grammar-designer.css'))

support=txt(Path('src/main/java/com/example/editor/integration/compiler/TechnologyAdapterTextualCustomizationSupport.java'))
fixtures=txt(Path('src/test/java/com/example/editor/integration/compiler/TechnologyAdapterTestFixtures.java'))
xtext_tests=txt(Path('src/test/java/com/example/editor/integration/adapter/xtext/XtextTechnologyAdapterTests.java'))
vscode_tests=txt(Path('src/test/java/com/example/editor/integration/adapter/vscode/VsCodeExtensionTechnologyAdapterTests.java'))
langium_tests=txt(Path('src/test/java/com/example/editor/integration/adapter/langium/LangiumTechnologyAdapterTests.java'))
eclipse_tests=txt(Path('src/test/java/com/example/editor/integration/adapter/eclipse/EclipseModelingDistributionTechnologyAdapterTests.java'))
conversion_tests=txt(Path('src/test/java/com/example/editor/grammar/application/GrammarPlatformConversionServiceTests.java'))
core_tests=txt(Path('src/test/java/com/example/editor/grammar/core/GrammarTextualEditorCustomizationTests.java'))
check('neutral customization is stored below hydra.textual settings', 'hydra.textual.' in core and 'applyTo' in core)
check('grammar designer exposes appearance tab', 'TEXTUAL_APPEARANCE' in designer and 'Editor appearance' in designer)
check('grammar designer exposes contextual hover tab', 'TEXTUAL_HOVER' in designer and 'Contextual information' in designer)
check('grammar designer exposes live preview tab', 'TEXTUAL_PREVIEW' in designer and 'Editor preview' in designer)
check('HYDRA textual model editor loads effective grammar customization', 'effectiveTextualCustomization' in textual and 'customization=' in textual)
check('Monaco applies role decorations', 'deltaDecorations' in monaco and 'styleClassName(style)' in monaco and 'hydra-textual-style-' in monaco)
check('Monaco registers hover provider', 'registerHoverProvider' in monaco)
check('standalone applies textual customization', 'hydra.textual.' in stand and 'hydra-textual-hover' in stand)
check('Xtext projection generates highlighting and hover', 'HydraHighlightingConfiguration.java' in xtext and 'HydraHoverProvider.java' in xtext)
check('Xtext current toolchain defaults to 2.44', '"2.44.0"' in xtext)
check('VS Code projection generates runtime customization', 'hydraTextualCustomization.ts' in vscode and 'registerHydraTextualCustomization' in vscode)
check('VS Code current Langium default is 4.3', '"4.3.0"' in vscode)
check('Langium projection includes TextMate customization', 'hydra-custom.tmLanguage.json' in langium)
check('Langium current default is 4.3', '"4.3.0"' in langium)
check('integration designer exposes grammar artifact', "'GRAMMAR'" in integration and "'TEXTUAL_EDITOR_DEFINITION'" in integration and "'TEXTUAL_SYNTAX_STYLE'" in integration)
check('new role CSS does not use important', all('!important' not in line for line in css.splitlines() if 'hydra-textual-role-' in line))
check('VS Code runtime consumes multiple syntax roles with bounded decorations', 'MAX_DECORATIONS=50000' in support and "style('STRING')" in support and "style('NUMBER')" in support and "style('COMMENT')" in support and 'setTimeout(()=>refreshNow(editor),120)' in support)
check('Xtext projection consumes font background and standard syntax roles', 'new FontData(FONT,SIZE,swt)' in support and 'setBackgroundColor(BACKGROUND)' in support and 'keywordTextStyle()' in support and 'commentTextStyle()' in support)
check('Xtext hover resolves semantic type as well as label', '.equals(type)' in support and '.equals(label)' in support)
check('Langium only contributes custom TextMate grammar when customization exists', 'boolean textualCustomization' in langium and 'grammarContribution = textualCustomization' in langium)
check('adapter regression fixtures carry a non-default neutral customization', 'hydra.textual.fontFamily' in fixtures and 'hydra.textual.hover.Person.description' in fixtures)
check('Xtext customization has a permanent adapter regression', 'consumesNeutralTextualCustomizationInXtextUi' in xtext_tests)
check('VS Code customization has a permanent adapter regression', 'consumesNeutralTextualCustomizationInVsCodeRuntime' in vscode_tests)
check('Langium customization has a permanent adapter regression', 'contributesCustomizedTextMateGrammarOnlyWhenGrammarIsSelected' in langium_tests)
check('Eclipse distribution customization has a permanent adapter regression', 'embedsNeutralTextualCustomizationInEclipseDistribution' in eclipse_tests)
check('platform conversion preserves neutral textual customization', 'preservesNeutralTextualCustomizationAcrossPlatformConversions' in conversion_tests and 'containsAllEntriesOf(settings)' in conversion_tests)
check('customization sanitization and round-trip have permanent regressions', 'sanitizesAndRoundTripsDeclarativeCustomization' in core_tests and 'boundsUnsafeValuesInsteadOfAcceptingExecutableStyling' in core_tests)
failed=[l for l,v in checks if not v]
for l,v in checks: print(('PASS' if v else 'FAIL')+' - '+l)
print(f'V43311_TEXTUAL_CUSTOMIZATION_EXPORT={len(checks)-len(failed)}/{len(checks)}')
raise SystemExit(1 if failed else 0)
